<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Announcement; use Illuminate\Http\Request;
class AnnouncementController extends Controller {public function index(){return view('admin.announcements.index',['items'=>Announcement::latest()->paginate(40)]);} public function store(Request $r){Announcement::create($this->data($r)+['author_id'=>auth()->id()]);return back()->with('ok','Объявление опубликовано');} public function update(Request $r,Announcement $announcement){$announcement->update($this->data($r));return back()->with('ok','Объявление сохранено');} public function destroy(Announcement $announcement){$announcement->delete();return back()->with('ok','Объявление удалено');} private function data(Request $r){return $r->validate(['title'=>'required|max:255','body'=>'required|string','program_id'=>'nullable|exists:programs,id','published_at'=>'nullable|date'])+['is_active'=>$r->boolean('is_active'),'published_at'=>$r->input('published_at')?:now()];} }